# --- Auto-Template: "Bilde Woerter/Wörter aus X!" + Restpruefung ---
import json as _json, re as _re
union=_json.load(open('/tmp/miss_union.json',encoding='utf-8'))
_bilde=_re.compile(r'^Bilde W(?:ö|oe)rter aus (.+?)!$')
for s in union:
    if s in T: continue
    m=_bilde.match(s)
    if m:
        x=m.group(1)
        T[s]=("Form words from %s!"%x, "Ułóż słowa z %s!"%x)
still=[s for s in union if s not in T]
print("Noch fehlend nach Template:",len(still))
for s in still[:60]: print("  MISS:",repr(s))
# EN/PL Maps schreiben (nur Strings, die auch wirklich genutzt werden)
en={s:T[s][0] for s in union if s in T}
pl={s:T[s][1] for s in union if s in T}
out={"en":en,"pl":pl}
_json.dump(out,open('data/i18n_extra.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
print("data/i18n_extra.json geschrieben: en=%d pl=%d"%(len(en),len(pl)))

# --- Nachzuegler (inkl. Verkettungs-Fragmente) ---
T.update({
 "Wo hat das Entwicklerstudio von ": ("Where is the studio behind ", "Gdzie ma siedzibę studio gry "),
 " seinen Hauptsitz?": (" headquartered?", "?"),
 "📍 Wo befindet sich dieses Kunstwerk?": ("📍 Where is this artwork?", "📍 Gdzie znajduje się to dzieło sztuki?"),
 "Welches Land hat die höhere Durchschnittstemperatur?": ("Which country has the higher average temperature?", "Który kraj ma wyższą średnią temperaturę?"),
})
en2={s:T[s][0] for s in union if s in T}
pl2={s:T[s][1] for s in union if s in T}
_json.dump({"en":en2,"pl":pl2},open('data/i18n_extra.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
_still2=[s for s in union if s not in T]
print("Endgueltig fehlend:",len(_still2),_still2)
print("data/i18n_extra.json: en=%d pl=%d"%(len(en2),len(pl2)))

